import React, { useState } from 'react';
import { getAuthToken } from '../services/authStorage';

const initialForm = {
  agent_name: '', agent_number: '', store_number: '', business_owner_name: '', contact_phone: '', id_number: '', business_location: '', date_visited: new Date().toISOString().slice(0, 10), registration_date: '', admin_name: '', witness_name: '', witness_id_number: '', witness_phone: '', customer_type: '', outcome: '', visit_mode: 'field_visit', notes: '', commission_statement: 'false', kra_pin: 'false', national_id: 'false', business_permit: 'false', contract: 'false',
};

export default function SalesDailyReportForm({ onSubmitted }) {
  const [form, setForm] = useState(initialForm);
  const [documents, setDocuments] = useState([]);
  const [submitting, setSubmitting] = useState(false);
  const [feedback, setFeedback] = useState(null);
  const update = (name, value) => setForm((current) => ({ ...current, [name]: value }));

  const submit = async (event) => {
    event.preventDefault();
    setSubmitting(true);
    setFeedback(null);
    try {
      const body = new FormData();
      Object.entries(form).forEach(([name, value]) => body.append(name, value));
      documents.forEach((file) => body.append('documents', file));
      const response = await fetch('/api/sales/reports', { method: 'POST', headers: { Authorization: `Bearer ${getAuthToken()}` }, body });
      const payload = await response.json();
      if (!response.ok) throw new Error(payload.error?.message || 'Unable to submit daily report.');
      setForm({ ...initialForm, date_visited: new Date().toISOString().slice(0, 10) });
      setDocuments([]);
      setFeedback({ type: 'success', text: payload.message || 'Daily sales report submitted.' });
      if (onSubmitted) onSubmitted(payload.data);
    } catch (error) {
      setFeedback({ type: 'error', text: error.message });
    } finally { setSubmitting(false); }
  };

  const fields = [['agent_name', 'Agent name'], ['agent_number', 'Agent number'], ['store_number', 'Store number'], ['business_owner_name', "Business owner's name"], ['contact_phone', 'Contact / phone number'], ['id_number', 'ID number'], ['business_location', 'Business location'], ['date_visited', 'Date visited'], ['registration_date', 'Registration date'], ['admin_name', 'Admin'], ['witness_name', 'Witness name'], ['witness_id_number', 'Witness ID number'], ['witness_phone', 'Witness contact / phone']];
  return <section className="leave-section sales-report-section" id="sales-daily-report"><div className="leave-section-heading"><div><p className="leave-kicker">SALES AND MARKETING</p><h2>Daily client visit report</h2><p className="leave-muted">Record every client visit, registration, appointment, and follow-up.</p></div></div>{feedback && <div className={`leave-alert ${feedback.type}`} role="status">{feedback.text}</div>}<form className="sales-report-form" onSubmit={submit}><div className="sales-report-grid">{fields.map(([name, label]) => <label key={name}>{label}<input type={name.includes('date') ? 'date' : 'text'} value={form[name]} onChange={(event) => update(name, event.target.value)} required={['agent_name', 'date_visited'].includes(name)} /></label>)}<label>Customer type<select value={form.customer_type} onChange={(event) => update('customer_type', event.target.value)} required><option value="">Select type</option><option value="agent">Agent / M-Pesa dealer</option><option value="sub_agent">Sub-agent</option></select></label><label>Visit outcome<select value={form.outcome} onChange={(event) => update('outcome', event.target.value)} required><option value="">Select outcome</option><option value="registered">Registered</option><option value="appointment">Appointment requested</option><option value="undecided">Undecided</option><option value="promised">Promised to adopt later</option><option value="declined">Declined</option></select></label><label>Visit mode<select value={form.visit_mode} onChange={(event) => update('visit_mode', event.target.value)}><option value="field_visit">Field visit</option><option value="telesales">Telesales</option></select></label></div><fieldset className="sales-documents"><legend>Documents submitted</legend><div className="sales-checkbox-grid">{[['commission_statement', 'Commission statement'], ['kra_pin', 'KRA PIN'], ['national_id', 'Copy of national ID'], ['business_permit', 'Business permit'], ['contract', 'Contract between agent and sub-agent']].map(([name, label]) => <label key={name}><input type="checkbox" checked={form[name] === 'true'} onChange={(event) => update(name, String(event.target.checked))} /> {label}</label>)}</div><label className="sales-upload">Upload supporting documents<input type="file" multiple onChange={(event) => setDocuments(Array.from(event.target.files || []))} /></label></fieldset><label>Visit notes<textarea value={form.notes} onChange={(event) => update('notes', event.target.value)} rows="4" placeholder="Record the discussion, next steps, and follow-up date." /></label><div className="leave-modal-actions"><button type="submit" className="leave-primary-button" disabled={submitting}>{submitting ? 'Submitting...' : 'Submit daily report'}</button></div></form></section>;
}
